const lesson9Data={"title":"你见过熊猫吗？","pinyin":"Nǐ jiànguo xióngmāo ma?","vi":"Bạn đã từng thấy gấu trúc chưa?","rows":[["打算","dǎsuàn","dự định; kế hoạch","这个周末你打算去哪儿？","Zhège zhōumò nǐ dǎsuàn qù nǎr?","Cuối tuần này bạn định đi đâu?"],["已经","yǐjīng","đã","我已经去过动物园了。","Wǒ yǐjīng qùguo dòngwùyuán le.","Tôi đã từng đến sở thú rồi."],["地方","dìfang","nơi; địa điểm","你去过哪些地方？","Nǐ qùguo nǎxiē dìfang?","Bạn đã đến những nơi nào?"],["建议","jiànyì","lời khuyên; đề nghị","你有什么建议？","Nǐ yǒu shénme jiànyì?","Bạn có đề nghị gì không?"],["过","guo","trợ từ chỉ trải nghiệm đã từng","我吃过中国菜。","Wǒ chīguo Zhōngguócài.","Tôi đã từng ăn món Trung."],["熊猫","xióngmāo","gấu trúc","你见过熊猫吗？","Nǐ jiànguo xióngmāo ma?","Bạn đã từng thấy gấu trúc chưa?"],["功夫熊猫","Gōngfu Xióngmāo","Kung Fu Panda (tên phim)","我看过电影《功夫熊猫》。","Wǒ kànguo diànyǐng Gōngfu Xióngmāo.","Tôi đã xem phim Kung Fu Panda."],["郊区","jiāoqū","ngoại ô","动物园在郊区。","Dòngwùyuán zài jiāoqū.","Sở thú ở ngoại ô."],["动物园","dòngwùyuán","sở thú","我们周末去动物园吧。","Wǒmen zhōumò qù dòngwùyuán ba.","Cuối tuần chúng ta đi sở thú nhé."],["……极了","…jí le","cực kỳ; vô cùng","这里的风景美极了。","Zhèlǐ de fēngjǐng měi jí le.","Phong cảnh ở đây đẹp vô cùng."],["对……感兴趣","duì…gǎn xìngqù","có hứng thú với…","我对动物很感兴趣。","Wǒ duì dòngwù hěn gǎn xìngqù.","Tôi rất có hứng thú với động vật."],["的话","dehuà","nếu… (điều kiện)","你感兴趣的话，我们一起去吧。","Nǐ gǎn xìngqù dehuà, wǒmen yìqǐ qù ba.","Nếu bạn thích thì chúng ta cùng đi nhé."],["约会","yuēhuì","hẹn hò; cuộc hẹn","他周末要跟女朋友约会。","Tā zhōumò yào gēn nǚpéngyou yuēhuì.","Cuối tuần anh ấy hẹn hò với bạn gái."],["遗憾","yíhàn","tiếc; đáng tiếc","真遗憾，你不能一起去。","Zhēn yíhàn, nǐ bù néng yìqǐ qù.","Tiếc thật, bạn không thể đi cùng."],["市中心","shìzhōngxīn","trung tâm thành phố","我想去市中心的博物馆。","Wǒ xiǎng qù shìzhōngxīn de bówùguǎn.","Tôi muốn đến bảo tàng ở trung tâm thành phố."],["感谢","gǎnxiè","cảm ơn","你怎么感谢我？","Nǐ zěnme gǎnxiè wǒ?","Bạn cảm ơn tôi thế nào?"],["烤鸭","kǎoyā","vịt quay","你吃过北京烤鸭吗？","Nǐ chīguo Běijīng kǎoyā ma?","Bạn đã ăn vịt quay Bắc Kinh chưa?"],["味道","wèidao","mùi vị","这个菜的味道好极了。","Zhège cài de wèidao hǎo jí le.","Món này có hương vị ngon tuyệt."],["肚子","dùzi","bụng","我的肚子已经饿了。","Wǒ de dùzi yǐjīng è le.","Bụng tôi đã đói rồi."]],"aliases":{"动物园":["动物"],"对……感兴趣":["对","感","兴趣"]},"dialogues":[["01 · Gợi ý đi sở thú",[["王文丽","欧文，这个周末你打算去哪儿？","Ōuwén, zhège zhōumò nǐ dǎsuàn qù nǎr?","Owen, cuối tuần này bạn định đi đâu?"],["欧文","我觉得好玩儿的地方都已经去过了，文丽，你有什么建议？","Wǒ juéde hǎowánr de dìfang dōu yǐjīng qùguo le, Wénlì, nǐ yǒu shénme jiànyì?","Những nơi tôi thấy thú vị thì đều đã đến rồi. Văn Lệ, bạn có gợi ý gì không?"],["王文丽","我想一下……你见过熊猫吗？","Wǒ xiǎng yíxià… Nǐ jiànguo xióngmāo ma?","Để tôi nghĩ… Bạn đã thấy gấu trúc chưa?"],["欧文","熊猫？我还没见过真的熊猫，可是我看过电影《功夫熊猫》。哪儿有熊猫？","Xióngmāo? Wǒ hái méi jiànguo zhēn de xióngmāo, kěshì wǒ kànguo diànyǐng Gōngfu Xióngmāo. Nǎr yǒu xióngmāo?","Gấu trúc à? Tôi chưa thấy gấu trúc thật, nhưng đã xem Kung Fu Panda. Ở đâu có gấu trúc?"],["王文丽","郊区的动物园里就有。","Jiāoqū de dòngwùyuán lǐ jiù yǒu.","Sở thú ở ngoại ô có đấy."],["欧文","真的？你去过那儿吗？","Zhēn de? Nǐ qùguo nàr ma?","Thật à? Bạn đã đến đó chưa?"],["王文丽","去过！那儿的熊猫可爱极了！你对动物感兴趣的话，可以去动物园。","Qùguo! Nàr de xióngmāo kě'ài jí le! Nǐ duì dòngwù gǎn xìngqù dehuà, kěyǐ qù dòngwùyuán.","Đến rồi! Gấu trúc ở đó đáng yêu vô cùng! Nếu thích động vật thì bạn có thể đến sở thú."],["欧文","当然感兴趣，那我去动物园吧。你可以跟我一起去吗？一个人去没意思。","Dāngrán gǎn xìngqù, nà wǒ qù dòngwùyuán ba. Nǐ kěyǐ gēn wǒ yìqǐ qù ma? Yí ge rén qù méi yìsi.","Tất nhiên là thích, vậy tôi đi sở thú. Bạn đi cùng được không? Đi một mình chán lắm."],["王文丽","不好意思，我周末没空儿，我要……","Bù hǎoyìsi, wǒ zhōumò méi kòngr, wǒ yào…","Ngại quá, cuối tuần tôi bận, tôi phải…"],["欧文","我知道，你要跟男朋友约会吧？","Wǒ zhīdào, nǐ yào gēn nánpéngyou yuēhuì ba?","Tôi biết rồi, bạn hẹn hò với bạn trai chứ gì?"]]],["02 · Bảo tàng và vịt quay",[["欧文","海伦，你去过郊区的动物园吗？","Hǎilún, nǐ qùguo jiāoqū de dòngwùyuán ma?","Helen, bạn đã đến sở thú ở ngoại ô chưa?"],["海伦","没去过，我对动物不太感兴趣。","Méi qùguo, wǒ duì dòngwù bú tài gǎn xìngqù.","Chưa, tôi không hứng thú lắm với động vật."],["欧文","真遗憾！我周末想去动物园，打算请你一起去。","Zhēn yíhàn! Wǒ zhōumò xiǎng qù dòngwùyuán, dǎsuàn qǐng nǐ yìqǐ qù.","Tiếc thật! Cuối tuần tôi muốn đến sở thú, định mời bạn đi cùng."],["海伦","我对博物馆很感兴趣，周末想去市中心的博物馆。欧文，你去过吗？","Wǒ duì bówùguǎn hěn gǎn xìngqù, zhōumò xiǎng qù shìzhōngxīn de bówùguǎn. Ōuwén, nǐ qùguo ma?","Tôi rất thích bảo tàng, cuối tuần muốn đến bảo tàng ở trung tâm thành phố. Owen, bạn đã đến chưa?"],["欧文","当然去过，我很喜欢参观博物馆。","Dāngrán qùguo, wǒ hěn xǐhuan cānguān bówùguǎn.","Tất nhiên đã đến, tôi rất thích tham quan bảo tàng."],["海伦","那这个星期六跟我再去一次，好吗？","Nà zhège xīngqīliù gēn wǒ zài qù yí cì, hǎo ma?","Vậy thứ Bảy này đi cùng tôi thêm một lần nhé?"],["欧文","好吧。你怎么感谢我？","Hǎo ba. Nǐ zěnme gǎnxiè wǒ?","Được thôi. Bạn cảm ơn tôi thế nào?"],["海伦","星期六晚上我请你吃烤鸭吧，你吃没吃过烤鸭？","Xīngqīliù wǎnshang wǒ qǐng nǐ chī kǎoyā ba, nǐ chī méi chīguo kǎoyā?","Tối thứ Bảy tôi mời bạn ăn vịt quay nhé. Bạn đã ăn vịt quay chưa?"],["欧文","没吃过，听说很好吃。","Méi chīguo, tīngshuō hěn hǎochī.","Chưa, nghe nói ngon lắm."],["海伦","当然，味道好极了。","Dāngrán, wèidao hǎo jí le.","Tất nhiên, hương vị ngon tuyệt."],["欧文","我的肚子已经饿了，现在就去吃吧！","Wǒ de dùzi yǐjīng è le, xiànzài jiù qù chī ba!","Bụng tôi đói rồi, đi ăn ngay bây giờ đi!"]]]],"reading":"田中、欧文和文丽是好朋友，这个周末他们想一起去玩儿，去哪儿呢？欧文很喜欢动物，他想去郊区的动物园看熊猫，因为他没去过，可是田中和文丽都不感兴趣，他们都不想去。田中建议去吃烤鸭，可是文丽说上个星期吃过，不喜欢烤鸭的味道。文丽打算去博物馆，欧文已经去过，但是还想去。田中也有兴趣。他们决定一起去。","exercises":{"vocab":[["你吃过北京（　）吗？","烤鸭","北京烤鸭 — vịt quay Bắc Kinh."],["你对什么感（　）？","兴趣","对……感兴趣 — hứng thú với…"],["我不知道去哪儿旅行，你有什么（　）？","建议","建议 — lời khuyên, gợi ý."],["我觉得中国菜好吃（　）。","极了","Tính từ + 极了: cực kỳ…"],["他常常跟女朋友（　）。","约会","约会 — hẹn hò."]],"reading":[["欧文很喜欢（　）。","动物","动物 là từ đi kèm 动物园 trong sách."],["可是田中和文丽都不感（　）。","兴趣","不感兴趣 — không hứng thú."],["文丽不喜欢烤鸭的（　）。","味道","味道 — mùi vị."],["文丽打算去（　）。","博物馆","Cuối cùng cả ba cùng đi bảo tàng."]],"choose":[["你吃（　）四川菜吧？味道怎么样？（没／过／了）","过","过 chỉ trải nghiệm từng ăn."],["她今天穿（　）一件漂亮的衣服，大家都说很好看。（没／过／了）","了","了 diễn tả hành động mặc hôm nay."],["我（　）看过中国电影，不知道好不好看。（没／过／了）","没","没 + động từ + 过 phủ định trải nghiệm."]],"comprehension":[["谁没去过郊区的动物园？",["田中","欧文","文丽","文丽和田中"],1],["谁想吃烤鸭？",["田中","欧文","文丽","文丽和田中"],0],["谁不想去看动物？",["田中","欧文","文丽","文丽和田中"],3],["谁对烤鸭不感兴趣？",["田中","欧文","文丽","文丽和田中"],2]]}};
